var o=[{title:`Condição física geral`,text:`O objetivo é uma capacidade e uma saúde amplas: treino de resistência para os principais padrões de movimento, atividade aeróbica regular e algum trabalho de mobilidade e equilíbrio. As sessões podem usar intervalos de repetições moderados e o equipamento que tiver. O progresso pode significar mais atividade semanal, mais energia durante o dia ou melhor desempenho nas flexões e na caminhada.`},{title:`Força`,text:`A prioridade é produzir mais força nos movimentos que escolhe. Um programa de força costuma colocar os levantamentos principais no início da sessão, aumentar a resistência com o tempo e usar descansos mais longos, para que a técnica e o desempenho se mantenham fortes. Cargas mais altas ajudam mais na força máxima, mas os principiantes podem ficar mais fortes sem nunca testar o seu máximo.`},{title:`Condicionamento`,text:`A prioridade é sustentar o esforço, recuperar entre esforços intensos ou melhorar a capacidade cardiovascular. Caminhar a ritmo constante, andar de bicicleta, correr e os intervalos são ferramentas para isto. A quantidade de trabalho fácil e difícil depende do seu nível de condição física, da preferência, da tolerância ao impacto e do equipamento. Nem todos os treinos de condicionamento devem parecer uma corrida.`},{title:`Exemplo`,text:`Imagine que tem três sessões de 40 minutos por semana. Para uma base de condição física geral, pode usar duas para resistência de corpo inteiro e uma para cardio. Um bloco de força pode manter essas duas sessões de resistência, acrescentar uma terceira sessão de levantamentos e manter alguma atividade aeróbica curta. Um bloco de condicionamento pode deslocar-se para o trabalho aeróbico, mantendo pelo menos duas sessões de força por semana quando possível.`},{title:`Sobreposição entre objetivos`,text:`O treino de resistência pode melhorar a resistência muscular, e o treino aeróbico pode ajudar na recuperação e na saúde. Os objetivos diferem na ênfase e sobrepõem-se muito. Escolha um objetivo principal durante quatro a oito semanas e depois veja os resultados antes de mudar de prioridades. Mudar após cada treino torna o progresso difícil de avaliar.`},{title:`Usar o TrainUp`,text:`Define o seu objetivo (condição física geral, força ou condicionamento) no Perfil. Seja qual for o objetivo, o seu equipamento, espaço e limitações decidem que exercícios podem entrar no plano.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Recomendações da OMS sobre atividade física`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};